-- Catalogue complet Warhammer 40,000 (kits et ensembles en boîte, Warhammer.com France).
-- Relevé des prix et visuels : 2026-11-04. Noms du catalogue français lorsque disponibles.
-- Les descriptions détaillées restent vides pour les fiches non accessibles; résumés déjà présents conservés.
-- Sont écartés : références sans prix public et produits Horus Heresy / Adeptus Titanicus hors périmètre 40K.
create table if not exists public.catalog_items (
  id text primary key,
  universe text not null default 'Warhammer 40,000',
  faction text not null,
  name text not null,
  description text not null,
  price_eur numeric(8,2) not null check (price_eur >= 0),
  image_url text,
  product_url text not null,
  price_source text not null default 'Warhammer.com',
  price_checked_at date not null default date '2026-11-04'
);

alter table public.catalog_items enable row level security;
drop policy if exists "Signed-in users read catalog" on public.catalog_items;
drop policy if exists "Anyone reads public catalog" on public.catalog_items;
create policy "Anyone reads public catalog" on public.catalog_items
  for select to anon, authenticated using (true);
revoke all on public.catalog_items from public, anon, authenticated;
grant select on public.catalog_items to anon, authenticated;

on conflict (id) do update set
  universe=excluded.universe, faction=excluded.faction, name=excluded.name,
  description=case when excluded.description <> '' then excluded.description else catalog_items.description end,
  price_eur=excluded.price_eur, image_url=excluded.image_url, product_url=excluded.product_url,
  price_source=excluded.price_source, price_checked_at=excluded.price_checked_at;
